#!/usr/bin/env python3
import sys
from itertools import product


def solve(H, W, K, C):
    cnt = 0
    L1 = list(product([True, False], repeat=H))
    L2 = list(product([True, False], repeat=W))
    for l1 in L1:
        for l2 in L2:
            num = 0
            for i in range(H):
                if not l1[i]:
                    continue
                for j in range(W):
                    if not l2[j]:
                        continue
                    num += C[i][j]
            if num == K:
                cnt += 1
    print(cnt)
    return

# Generated by 1.1.7.1 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    # Failed to predict input format
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    H = int(next(tokens))
    W = int(next(tokens))
    K = int(next(tokens))
    C = [[0 for _ in range(W)] for _ in range(H)]
    for i in range(H):
        col = next(tokens)
        for j in range(W):
            C[i][j] = 1 if col[j] == "#" else 0
    solve(H, W, K, C)

if __name__ == '__main__':
    main()